// Nim: wejście n, potem rozmiary stosów. Wyjście: kto wygrywa i (dla pierwszego) ruch wygrywający:
// numer stosu i jego nowy rozmiar.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    long long s = 0;
    for (auto &x : a) { cin >> x; s ^= x; }
    if (s == 0) { cout << "Drugi\n"; return 0; }      // każdy ruch psuje XOR = 0
    cout << "Pierwszy\n";
    for (int i = 0; i < n; i++)
        if ((a[i] ^ s) < a[i]) {                       // stos ma ustawiony najstarszy bit s
            cout << i + 1 << " " << (a[i] ^ s) << "\n";  // po ruchu XOR = 0
            break;
        }
}

