// Gra odejmowania: z dowolnego stosu wolno zabrać s żetonów, s należy do S. Wiele stosów.
// Wejście: k, elementy S, m, rozmiary stosów (do 10^6). Wyjście: wartości Grundy'ego stosów i zwycięzca.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int k;
    cin >> k;
    vector<int> S(k);
    for (auto &s : S) cin >> s;
    int m;
    cin >> m;
    vector<int> piles(m);
    for (auto &p : piles) cin >> p;
    int N = *max_element(piles.begin(), piles.end());

    vector<int> g(N + 1, 0);
    vector<int> seenAt(k + 2, -1);                 // mex: wartości g <= k, więc wystarczy k+2 pól
    for (int n = 1; n <= N; n++) {
        for (int s : S) if (s <= n) seenAt[g[n - s]] = n;   // znacznik "widziane w kroku n"
        int mex = 0;
        while (seenAt[mex] == n) mex++;
        g[n] = mex;
    }
    int x = 0;
    for (int p : piles) { cout << g[p] << " "; x ^= g[p]; }
    cout << "\n" << (x ? "Pierwszy" : "Drugi") << "\n";
}

