// Analiza wsteczna: n wierzchołków, m krawędzi skierowanych u -> v. Dla każdego wierzchołka W / L / D.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> radj(n + 1);           // krawędzie odwrócone: v -> poprzednicy
    vector<int> cnt(n + 1, 0);                 // liczba jeszcze niezbadanych ruchów z u
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        radj[v].push_back(u);
        cnt[u]++;
    }
    vector<int> res(n + 1, 0);                 // 0 = nieznany (remis), 1 = W, -1 = L
    queue<int> q;
    for (int v = 1; v <= n; v++)
        if (cnt[v] == 0) { res[v] = -1; q.push(v); }   // brak ruchu = przegrana
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u : radj[v]) {
            if (res[u] != 0) continue;
            if (res[v] == -1) { res[u] = 1; q.push(u); }            // ruch do L => W
            else if (--cnt[u] == 0) { res[u] = -1; q.push(u); }     // wszystkie ruchy do W => L
        }
    }
    for (int v = 1; v <= n; v++) cout << (res[v] == 1 ? 'W' : res[v] == -1 ? 'L' : 'D') << " ";
    cout << "\n";
}

