// Weryfikacja brute force: gracze kładą na zmianę kostki domina 1x2 na planszy n x m (n*m <= 20);
// kto nie może położyć, przegrywa. Hipoteza z symetrii: obie strony parzyste -> wygrywa Drugi
// (lustro względem środka); dokładnie jedna parzysta -> Pierwszy (środkowe domino, potem lustro).
#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<signed char> memo;                    // -1 nieznane, 0 przegrywa gracz na ruchu, 1 wygrywa

bool win(int mask) {                         // mask = zajęte pola
    if (memo[mask] != -1) return memo[mask];
    bool res = false;
    for (int a = 0; a < n * m && !res; a++) {
        if (mask >> a & 1) continue;
        int r = a / m, c = a % m;
        if (c + 1 < m && !(mask >> (a + 1) & 1) && !win(mask | 1 << a | 1 << (a + 1))) res = true;
        if (!res && r + 1 < n && !(mask >> (a + m) & 1) && !win(mask | 1 << a | 1 << (a + m))) res = true;
    }
    memo[mask] = res;
    return res;
}

int main() {
    cin >> n >> m;
    memo.assign(1 << (n * m), -1);
    cout << (win(0) ? "Pierwszy" : "Drugi") << "\n";
}

